// USCIS 2025 Civics Test - 128 Questions
// Source: USCIS M-1778 (09/25)
// Questions marked with starred: true are for the 65/20 special consideration

export const questions = [
  // AMERICAN GOVERNMENT - Principles (1-15)
  { id: 1, question: "What is the form of government of the United States?", requiredAnswers: 1, acceptableAnswers: ["Republic", "Constitution-based federal republic", "Representative democracy"], category: "Principles of American Government", starred: false, funFact: "The U.S. is technically not a pure democracy—it's a republic where we elect representatives.", mnemonic: "Think 'Republic' - we elect representatives who then make decisions for us. REP = Representatives Elected by People!" },
  { id: 2, question: "What is the supreme law of the land?", requiredAnswers: 1, acceptableAnswers: ["(U.S.) Constitution", "Constitution", "The Constitution"], category: "Principles of American Government", starred: true, funFact: "The Constitution is just 4,543 words—shorter than most terms of service agreements!", mnemonic: "SUPREme law = CONSTITUTION. Both sound official and important. Nothing is above the Constitution!" },
  { id: 3, question: "Name one thing the U.S. Constitution does.", requiredAnswers: 1, acceptableAnswers: ["Forms the government", "Defines powers of government", "Defines the parts of government", "Protects the rights of the people"], category: "Principles of American Government", starred: false, funFact: "The Constitution created a government that didn't exist before - it literally formed America!", mnemonic: "Constitution = Construction manual for building government! It Forms, Defines, and Protects." },
  { id: 4, question: "The U.S. Constitution starts with the words 'We the People.' What does 'We the People' mean?", requiredAnswers: 1, acceptableAnswers: ["Self-government", "Popular sovereignty", "Consent of the governed", "People should govern themselves", "(Example of) social contract"], category: "Principles of American Government", starred: false, funFact: "The Constitution begins with 'We the People' - not 'We the Government' - putting citizens first!", mnemonic: "WE = The PEOPLE run the government, not kings or queens. Self-government means WE decide!" },
  { id: 5, question: "How are changes made to the U.S. Constitution?", requiredAnswers: 1, acceptableAnswers: ["Amendments", "The amendment process"], category: "Principles of American Government", starred: false, funFact: "Amending the Constitution is super hard - needs 2/3 of Congress + 3/4 of states!", mnemonic: "AMEND = ADD or MEND. Like editing a document - you can amend (change) the Constitution!" },
  { id: 6, question: "What does the Bill of Rights protect?", requiredAnswers: 1, acceptableAnswers: ["(The basic) rights of Americans", "(The basic) rights of people living in the United States", "The rights of Americans", "The rights of people living in the United States"], category: "Principles of American Government", starred: false, funFact: "The Bill of Rights is the first 10 amendments - our most fundamental freedoms!", mnemonic: "Bill of RIGHTS = pays the bill for your RIGHTS! Protects basic freedoms of Americans." },
  { id: 7, question: "How many amendments does the U.S. Constitution have?", requiredAnswers: 1, acceptableAnswers: ["Twenty-seven (27)", "27", "Twenty-seven"], category: "Principles of American Government", starred: true, funFact: "The 27th Amendment took 202 years to ratify!", mnemonic: "Think 3 cubed (3³ = 27). Three branches of government, cubed!" },
  { id: 8, question: "Why is the Declaration of Independence important?", requiredAnswers: 1, acceptableAnswers: ["It says America is free from British control.", "It says all people are created equal.", "It identifies inherent rights.", "It identifies individual freedoms."], category: "Principles of American Government", starred: false, funFact: "The Declaration was signed on July 4, 1776 - that's why we celebrate the 4th of July!", mnemonic: "Declaration = DECLARES America is FREE! It's our breakup letter to Britain." },
  { id: 9, question: "What founding document said the American colonies were free from Britain?", requiredAnswers: 1, acceptableAnswers: ["Declaration of Independence", "The Declaration of Independence"], category: "Principles of American Government", starred: false, funFact: "56 brave men signed the Declaration - they risked being hanged as traitors!", mnemonic: "DECLARATION of INDEPENDENCE = We DECLARE our INDEPENDENCE from Britain!" },
  { id: 10, question: "Name two important ideas from the Declaration of Independence and the U.S. Constitution.", requiredAnswers: 2, acceptableAnswers: ["Equality", "Liberty", "Social contract", "Natural rights", "Limited government", "Self-government"], category: "Principles of American Government", starred: false, funFact: "These founding documents laid the foundation for democracies worldwide!", mnemonic: "Easy acronym: EL SN LS = Equality, Liberty, Social contract, Natural rights, Limited govt, Self-govt. Pick any 2!" },
  { id: 11, question: "The words 'Life, Liberty, and the pursuit of Happiness' are in what founding document?", requiredAnswers: 1, acceptableAnswers: ["Declaration of Independence", "The Declaration of Independence"], category: "Principles of American Government", starred: false, funFact: "Jefferson originally wrote 'property' instead of 'pursuit of Happiness'!", mnemonic: "Life, Liberty, Happiness = Declaration of Independence. These are our 'inalienable rights'!" },
  { id: 12, question: "What is the economic system of the United States?", requiredAnswers: 1, acceptableAnswers: ["Capitalism", "Free market economy", "Market economy"], category: "Principles of American Government", starred: true, funFact: "The U.S. has the world's largest economy, worth over $25 trillion!", mnemonic: "America = Capitalism. Both start with 'A' and 'C'. CAPITAL-ism needs CAPITAL (money) to thrive!" },
  { id: 13, question: "What is the rule of law?", requiredAnswers: 1, acceptableAnswers: ["Everyone must follow the law.", "Leaders must obey the law.", "Government must obey the law.", "No one is above the law."], category: "Principles of American Government", starred: false, funFact: "Even the President can be impeached and tried for breaking laws!", mnemonic: "Rule of Law = NO ONE is above the law. Even leaders must obey!" },
  { id: 14, question: "Many documents influenced the U.S. Constitution. Name one.", requiredAnswers: 1, acceptableAnswers: ["Declaration of Independence", "Articles of Confederation", "Federalist Papers", "Anti-Federalist Papers", "Virginia Declaration of Rights", "Fundamental Orders of Connecticut", "Mayflower Compact", "Iroquois Great Law of Peace"], category: "Principles of American Government", starred: false, funFact: "The Iroquois Great Law of Peace influenced the Constitution's federal system!", mnemonic: "Declaration of Independence is the easiest to remember - it influenced the Constitution!" },
  { id: 15, question: "There are three branches of government. Why?", requiredAnswers: 1, acceptableAnswers: ["So one part does not become too powerful", "Checks and balances", "Separation of powers"], category: "Principles of American Government", starred: false, funFact: "Montesquieu's idea of separation of powers inspired the Founding Fathers!", mnemonic: "3 branches = CHECKS and BALANCES. Each branch checks the others to prevent tyranny!" },

  // AMERICAN GOVERNMENT - System of Government (16-62)
  { id: 16, question: "Name the three branches of government.", requiredAnswers: 1, acceptableAnswers: ["Legislative, executive, and judicial", "Congress, president, and the courts"], category: "System of Government", starred: false, funFact: "The three branches are like rock-paper-scissors - each can beat another!", mnemonic: "LEJ: Legislative (makes laws), Executive (enforces laws), Judicial (judges laws)!" },
  { id: 17, question: "The President of the United States is in charge of which branch of government?", requiredAnswers: 1, acceptableAnswers: ["Executive branch", "The executive branch", "Executive"], category: "System of Government", starred: false, funFact: "The President is the chief executive - like a CEO of the country!", mnemonic: "President = EXECUTIVE branch. The President EXECUTES (carries out) the laws!" },
  { id: 18, question: "What part of the federal government writes laws?", requiredAnswers: 1, acceptableAnswers: ["(U.S.) Congress", "Congress", "(U.S. or national) legislature", "Legislative branch"], category: "System of Government", starred: false, funFact: "A bill must pass both the House AND Senate before becoming law!", mnemonic: "LEGISLATIVE = makes LEGISLATION (laws). Congress is the Legislative branch that WRITES laws!" },
  { id: 19, question: "What are the two parts of the U.S. Congress?", requiredAnswers: 1, acceptableAnswers: ["Senate and House (of Representatives)", "Senate and House", "The Senate and the House of Representatives"], category: "System of Government", starred: false, funFact: "The Senate has 100 members, the House has 435 - very different sizes!", mnemonic: "Two parts = Senate and House. Think of Congress as a two-story building: Upper House (Senate) and Lower House!" },
  { id: 20, question: "Name one power of the U.S. Congress.", requiredAnswers: 1, acceptableAnswers: ["Writes laws", "Declares war", "Makes the federal budget"], category: "System of Government", starred: true, funFact: "Congress has declared war 11 times in U.S. history, most recently in World War II!", mnemonic: "Congress makes LAWS - Legislative Authorities Write Statutes! Easy to remember the main power." },
  { id: 21, question: "How many U.S. senators are there?", requiredAnswers: 1, acceptableAnswers: ["One hundred (100)", "100", "One hundred"], category: "System of Government", starred: false, funFact: "With 2 senators per state × 50 states, we get the 100 senators!", mnemonic: "100 senators, like a perfect score - 100 years of hoping they'll all agree on something!" },
  { id: 22, question: "How long is a term for a U.S. senator?", requiredAnswers: 1, acceptableAnswers: ["Six (6) years", "6 years", "Six years"], category: "System of Government", starred: false, funFact: "Senate terms are staggered so only 1/3 of senators are up for election every 2 years.", mnemonic: "SIX years for SenatorS - both have that 'S' sound. Senators serve LONGER than House members (2 years)." },
  { id: 23, question: "Who is one of your state's U.S. senators now?", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "state_senators" }, category: "System of Government", starred: false, funFact: "Every state gets exactly 2 senators, no matter how big or small the state is!", mnemonic: "We've looked up your state's senators based on your ZIP code! Each state has exactly 2 senators." },
  { id: 24, question: "How many voting members are in the House of Representatives?", requiredAnswers: 1, acceptableAnswers: ["Four hundred thirty-five (435)", "435", "Four hundred thirty-five"], category: "System of Government", starred: false, funFact: "The House has been at 435 members since 1913, no matter how much the population grows!", mnemonic: "435: Add the digits → 4+3+5 = 12, like the 13 original colonies minus 1!" },
  { id: 25, question: "How long is a term for a member of the House of Representatives?", requiredAnswers: 1, acceptableAnswers: ["Two (2) years", "2 years", "Two years"], category: "System of Government", starred: false, funFact: "House members face re-election every 2 years to stay closely connected to voters!", mnemonic: "TWO years = TOO short! House members barely unpack before running for re-election again." },
  { id: 26, question: "Why do U.S. representatives serve shorter terms than U.S. senators?", requiredAnswers: 1, acceptableAnswers: ["To more closely follow public opinion"], category: "System of Government", starred: false, funFact: "House members are up for re-election every 2 years to stay connected to voters!", mnemonic: "House = 2 years = CLOSER to the people. Senators = 6 years = more INDEPENDENT thinking." },
  { id: 27, question: "How many senators does each state have?", requiredAnswers: 1, acceptableAnswers: ["Two (2)", "2", "Two"], category: "System of Government", starred: false, funFact: "California has the same 2 senators as tiny Rhode Island - perfect equality!", mnemonic: "2 senators per state. It takes TWO to tango - every state gets exactly TWO senators!" },
  { id: 28, question: "Why does each state have two senators?", requiredAnswers: 1, acceptableAnswers: ["Equal representation (for small states)", "The Great Compromise (Connecticut Compromise)", "Equal representation"], category: "System of Government", starred: false, funFact: "The Great Compromise balanced big states (who wanted population-based representation) and small states!", mnemonic: "EQUAL representation = 2 senators each. Small states wanted EQUAL say, so everyone gets 2!" },
  { id: 29, question: "Name your U.S. representative.", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "us_representative" }, category: "System of Government", starred: false, funFact: "Your House representative represents just your congressional district, not the whole state!", mnemonic: "We've found your U.S. representative based on your ZIP code. They represent YOUR district!" },
  { id: 30, question: "What is the name of the Speaker of the House of Representatives now?", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "speaker_of_house" }, category: "System of Government", starred: true, funFact: "The Speaker is 2nd in line for presidential succession, right after the VP!", mnemonic: "The Speaker SPEAKS for the House - they're the leader! Check news for current name." },
  { id: 31, question: "Who does a U.S. senator represent?", requiredAnswers: 1, acceptableAnswers: ["Citizens of their state", "People of their state"], category: "System of Government", starred: false, funFact: "Senators represent the entire state - all citizens, not just one district!", mnemonic: "Senator = STATE-wide representation. They represent ALL citizens of THEIR STATE!" },
  { id: 32, question: "Who elects U.S. senators?", requiredAnswers: 1, acceptableAnswers: ["Citizens from their state"], category: "System of Government", starred: false, funFact: "Before 1913, state legislatures chose senators - now WE vote directly (17th Amendment)!", mnemonic: "CITIZENS from their STATE elect senators. Voters in each state choose their 2 senators!" },
  { id: 33, question: "Who does a member of the House of Representatives represent?", requiredAnswers: 1, acceptableAnswers: ["Citizens in their (congressional) district", "Citizens in their district", "People from their (congressional) district", "People in their district"], category: "System of Government", starred: false, funFact: "Congressional districts are redrawn every 10 years after the census!", mnemonic: "House members = DISTRICT representation. They represent citizens in THEIR DISTRICT only!" },
  { id: 34, question: "Who elects members of the House of Representatives?", requiredAnswers: 1, acceptableAnswers: ["Citizens from their (congressional) district", "Citizens from their district"], category: "System of Government", starred: false, funFact: "You vote for YOUR district's representative - not representatives from other districts!", mnemonic: "Citizens from their DISTRICT elect House members. Only YOUR district votes for YOUR representative!" },
  { id: 35, question: "Some states have more representatives than other states. Why?", requiredAnswers: 1, acceptableAnswers: ["(Because of) the state's population", "(Because) they have more people", "(Because) some states have more people", "Population", "Because of population"], category: "System of Government", starred: false, funFact: "California has 52 representatives while Wyoming has only 1!", mnemonic: "MORE people = MORE representatives. Population determines House seats!" },
  { id: 36, question: "The President of the United States is elected for how many years?", requiredAnswers: 1, acceptableAnswers: ["Four (4) years", "4 years", "Four years"], category: "System of Government", starred: true, funFact: "Presidential elections happen in years divisible by 4 (2020, 2024, 2028...)", mnemonic: "FOUR years for FOUR letters in 'TERM'. Also, think of the 4 seasons - one full cycle!" },
  { id: 37, question: "The President of the United States can serve only two terms. Why?", requiredAnswers: 1, acceptableAnswers: ["(Because of) the 22nd Amendment", "To keep the president from becoming too powerful", "22nd Amendment"], category: "System of Government", starred: false, funFact: "FDR served 4 terms, so the 22nd Amendment was passed to limit presidents to 2 terms!", mnemonic: "22nd Amendment = 2 terms limit. Remember: TWO-TWO (22) means TWO terms max!" },
  { id: 38, question: "What is the name of the President of the United States now?", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "president" }, category: "System of Government", starred: true, funFact: "The President lives in the White House at 1600 Pennsylvania Avenue!", mnemonic: "This changes! Check recent news or the White House website. Remember the current President's name!" },
  { id: 39, question: "What is the name of the Vice President of the United States now?", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "vice_president" }, category: "System of Government", starred: true, funFact: "The Vice President is also the President of the Senate and casts tie-breaking votes!", mnemonic: "The VP is the President's 'backup' - if something happens to the President, VP takes over!" },
  { id: 40, question: "If the president can no longer serve, who becomes president?", requiredAnswers: 1, acceptableAnswers: ["The Vice President (of the United States)", "Vice President", "The Vice President"], category: "System of Government", starred: false, funFact: "9 vice presidents have become president due to death or resignation!", mnemonic: "VP = Vice President = backup plan. If President can't serve, the VICE President takes over!" },
  { id: 41, question: "Name one power of the president.", requiredAnswers: 1, acceptableAnswers: ["Signs bills into law", "Vetoes bills", "Enforces laws", "Commander in Chief (of the military)", "Chief diplomat", "Appoints federal judges"], category: "System of Government", starred: false, funFact: "The President has many powers but can't declare war - only Congress can!", mnemonic: "President's powers: Signs/Vetoes laws, Commander of military, Appoints judges. Pick ONE!" },
  { id: 42, question: "Who is Commander in Chief of the U.S. military?", requiredAnswers: 1, acceptableAnswers: ["The President (of the United States)", "President", "The President"], category: "System of Government", starred: false, funFact: "The President is Commander in Chief even though they don't need military experience!", mnemonic: "Commander in Chief = The PRESIDENT. Civilian control of military!" },
  { id: 43, question: "Who signs bills to become laws?", requiredAnswers: 1, acceptableAnswers: ["The President (of the United States)", "President", "The President"], category: "System of Government", starred: false, funFact: "The President's signature makes a bill official - it becomes law!", mnemonic: "President SIGNS bills = they become LAWS. President's signature = final approval!" },
  { id: 44, question: "Who vetoes bills?", requiredAnswers: 1, acceptableAnswers: ["The President (of the United States)", "President", "The President"], category: "System of Government", starred: true, funFact: "Presidents have vetoed over 2,500 bills throughout U.S. history!", mnemonic: "Veto = President says 'NO!' Think of the President as the final boss who can reject laws." },
  { id: 45, question: "Who appoints federal judges?", requiredAnswers: 1, acceptableAnswers: ["The President (of the United States)", "President", "The President"], category: "System of Government", starred: false, funFact: "The President nominates judges, but the Senate must confirm them!", mnemonic: "President APPOINTS judges. Think: President picks the team!" },
  { id: 46, question: "The executive branch has many parts. Name one.", requiredAnswers: 1, acceptableAnswers: ["President (of the United States)", "Cabinet", "Federal departments and agencies", "President"], category: "System of Government", starred: false, funFact: "The executive branch has over 4 million employees!", mnemonic: "Executive branch parts: President, Cabinet, or Federal agencies. Easy answers!" },
  { id: 47, question: "What does the President's Cabinet do?", requiredAnswers: 1, acceptableAnswers: ["Advises the President (of the United States)", "Advises the President"], category: "System of Government", starred: false, funFact: "The Cabinet is like the President's team of expert advisors!", mnemonic: "Cabinet = President's advisory board. They ADVISE the President on important issues!" },
  { id: 48, question: "What are two Cabinet-level positions?", requiredAnswers: 2, acceptableAnswers: ["Attorney General", "Secretary of Agriculture", "Secretary of Commerce", "Secretary of Defense", "Secretary of Education", "Secretary of Energy", "Secretary of Health and Human Services", "Secretary of Homeland Security", "Secretary of Housing and Urban Development", "Secretary of the Interior", "Secretary of Labor", "Secretary of State", "Secretary of Transportation", "Secretary of the Treasury", "Secretary of Veterans Affairs", "Vice President"], category: "System of Government", starred: false, funFact: "There are 15 Cabinet departments plus the VP and Attorney General!", mnemonic: "Easy ones: Secretary of State, Secretary of Defense. Or Vice President! Pick any 2!" },
  { id: 49, question: "Why is the Electoral College important?", requiredAnswers: 1, acceptableAnswers: ["It decides who is elected president.", "It provides a compromise between the popular election of the president and congressional selection."], category: "System of Government", starred: false, funFact: "You need 270 electoral votes to win the presidency (out of 538 total)!", mnemonic: "Electoral College DECIDES who becomes President. It's the system that actually elects the President!" },
  { id: 50, question: "What is one part of the judicial branch?", requiredAnswers: 1, acceptableAnswers: ["Supreme Court", "Federal Courts"], category: "System of Government", starred: false, funFact: "The judicial branch includes the Supreme Court plus hundreds of federal courts!", mnemonic: "Judicial branch = courts! Supreme Court or Federal Courts. Easy!" },
  { id: 51, question: "What does the judicial branch do?", requiredAnswers: 1, acceptableAnswers: ["Reviews laws", "Explains laws", "Resolves disputes (disagreements) about the law", "Decides if a law goes against the (U.S.) Constitution"], category: "System of Government", starred: false, funFact: "The Supreme Court can strike down laws as unconstitutional!", mnemonic: "JUDICIAL = JUDGES the law. Reviews, explains, and decides if laws are constitutional!" },
  { id: 52, question: "What is the highest court in the United States?", requiredAnswers: 1, acceptableAnswers: ["Supreme Court", "The Supreme Court"], category: "System of Government", starred: true, funFact: "The Supreme Court building has 'Equal Justice Under Law' inscribed above its entrance!", mnemonic: "SUPREME = HIGHEST. Supreme pizza = the one with EVERYTHING. Supreme Court = the top court!" },
  { id: 53, question: "How many seats are on the Supreme Court?", requiredAnswers: 1, acceptableAnswers: ["Nine (9)", "9", "Nine"], category: "System of Government", starred: false, funFact: "9 justices have been the standard since 1869, though Congress could change this number!", mnemonic: "9 justices, like a baseball team (9 players on the field)!" },
  { id: 54, question: "How many Supreme Court justices are usually needed to decide a case?", requiredAnswers: 1, acceptableAnswers: ["Five (5)", "5", "Five"], category: "System of Government", starred: false, funFact: "5 is a majority of 9 justices - you need more than half!", mnemonic: "5 out of 9 justices = MAJORITY. More than half decides the case!" },
  { id: 55, question: "How long do Supreme Court justices serve?", requiredAnswers: 1, acceptableAnswers: ["(For) life", "Lifetime appointment", "(Until) retirement", "Life", "For life"], category: "System of Government", starred: false, funFact: "Some justices have served over 35 years - it's a lifetime job!", mnemonic: "Supreme Court = LIFE appointment. They serve FOR LIFE or until retirement!" },
  { id: 56, question: "Supreme Court justices serve for life. Why?", requiredAnswers: 1, acceptableAnswers: ["To be independent (of politics)", "To limit outside (political) influence"], category: "System of Government", starred: false, funFact: "Lifetime appointments prevent justices from worrying about re-election!", mnemonic: "Life term = INDEPENDENT judgment. No fear of being fired = no political pressure!" },
  { id: 57, question: "Who is the Chief Justice of the United States now?", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "chief_justice" }, category: "System of Government", starred: false, funFact: "The Chief Justice leads the Supreme Court and presides over presidential impeachment trials!", mnemonic: "Chief Justice = head of the Supreme Court. Check current news for the name!" },
  { id: 58, question: "Name one power that is only for the federal government.", requiredAnswers: 1, acceptableAnswers: ["Print paper money", "Mint coins", "Declare war", "Create an army", "Make treaties", "Set foreign policy"], category: "System of Government", starred: false, funFact: "Only the federal government can print money - states can't make their own!", mnemonic: "FEDERAL powers: Print money, Declare war, Make treaties. National issues!" },
  { id: 59, question: "Name one power that is only for the states.", requiredAnswers: 1, acceptableAnswers: ["Provide schooling and education", "Provide protection (police)", "Provide safety (fire departments)", "Give a driver's license", "Approve zoning and land use"], category: "System of Government", starred: false, funFact: "Education and police are state powers - that's why schools vary by state!", mnemonic: "STATE powers: Schools, Police, Driver's licenses. Local issues!" },
  { id: 60, question: "What is the purpose of the 10th Amendment?", requiredAnswers: 1, acceptableAnswers: ["(It states that the) powers not given to the federal government belong to the states or to the people.", "Powers not given to the federal government belong to the states or to the people"], category: "System of Government", starred: false, funFact: "The 10th Amendment is about federalism - dividing power between national and state governments!", mnemonic: "10th Amendment = Leftover powers go to STATES or PEOPLE. If feds don't have it, states do!" },
  { id: 61, question: "Who is the governor of your state now?", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "state_governor" }, category: "System of Government", starred: true, funFact: "Governors are like mini-presidents for their states - they lead the state government!", mnemonic: "Governor GOVERNS your state. Look up your state's current governor before the test!" },
  { id: 62, question: "What is the capital of your state?", requiredAnswers: 1, acceptableAnswers: [], dynamicAnswer: { type: "state_capital" }, category: "System of Government", starred: false, funFact: "Every state has a capital where the state government is located!", mnemonic: "We've filled in your state capital based on your ZIP code. The capital is where your state government meets!" },

  // Rights and Responsibilities (63-72)
  { id: 63, question: "There are four amendments to the U.S. Constitution about who can vote. Describe one of them.", requiredAnswers: 1, acceptableAnswers: ["Citizens eighteen (18) and older (can vote).", "You don't have to pay (a poll tax) to vote.", "Any citizen can vote. (Women and men can vote.)", "A male citizen of any race (can vote)."], category: "Rights and Responsibilities", starred: false, funFact: "The 4 voting amendments: 15th (race), 19th (women), 24th (no poll tax), 26th (age 18+)!", mnemonic: "FOUR voting amendments: Age 18+, No poll tax, Women can vote, Any race can vote. Pick ONE!" },
  { id: 64, question: "Who can vote in federal elections, run for federal office, and serve on a jury in the United States?", requiredAnswers: 1, acceptableAnswers: ["Citizens", "Citizens of the United States", "U.S. citizens"], category: "Rights and Responsibilities", starred: false, funFact: "Only citizens have these special rights - not just residents!", mnemonic: "CITIZENS only! Vote, run for office, jury duty = citizen privileges!" },
  { id: 65, question: "What are three rights of everyone living in the United States?", requiredAnswers: 3, acceptableAnswers: ["Freedom of expression", "Freedom of speech", "Freedom of assembly", "Freedom to petition the government", "Freedom of religion", "The right to bear arms"], category: "Rights and Responsibilities", starred: false, funFact: "These rights apply to EVERYONE in the U.S., not just citizens!", mnemonic: "EVERYONE's rights: Speech, Religion, Assembly. First Amendment freedoms! Pick 3!" },
  { id: 66, question: "What do we show loyalty to when we say the Pledge of Allegiance?", requiredAnswers: 1, acceptableAnswers: ["The United States", "The flag"], category: "Rights and Responsibilities", starred: true, funFact: "The Pledge was written in 1892 and 'under God' was added in 1954!", mnemonic: "PLEDGE = Promise of loyalty. We pledge to the FLAG and the UNITED STATES it represents!" },
  { id: 67, question: "Name two promises that new citizens make in the Oath of Allegiance.", requiredAnswers: 2, acceptableAnswers: ["Give up loyalty to other countries", "Defend the (U.S.) Constitution", "Obey the laws of the United States", "Serve in the military (if needed)", "Serve (help, do important work for) the nation (if needed)", "Be loyal to the United States"], category: "Rights and Responsibilities", starred: false, funFact: "The Oath of Allegiance is recited at naturalization ceremonies!", mnemonic: "Oath promises: Give up old country, Defend Constitution, Obey laws, Be loyal. Pick 2!" },
  { id: 68, question: "How can people become United States citizens?", requiredAnswers: 1, acceptableAnswers: ["Be born in the United States, under the conditions set by the 14th Amendment", "Naturalize", "Derive citizenship (under conditions set by Congress)"], category: "Rights and Responsibilities", starred: false, funFact: "About 700,000 people naturalize as U.S. citizens each year!", mnemonic: "3 ways: Born here, Naturalize (apply), or Derive (from parents). Easy!" },
  { id: 69, question: "What are two examples of civic participation in the United States?", requiredAnswers: 2, acceptableAnswers: ["Vote", "Run for office", "Join a political party", "Help with a campaign", "Join a civic group", "Join a community group", "Give an elected official your opinion (on an issue)", "Contact elected officials", "Support or oppose an issue or policy", "Write to a newspaper"], category: "Rights and Responsibilities", starred: false, funFact: "Civic participation strengthens democracy - it's how citizens make their voices heard!", mnemonic: "Easy ones: VOTE and Run for office. Or contact officials. Pick 2!" },
  { id: 70, question: "What is one way Americans can serve their country?", requiredAnswers: 1, acceptableAnswers: ["Vote", "Pay taxes", "Obey the law", "Serve in the military", "Run for office", "Work for local, state, or federal government"], category: "Rights and Responsibilities", starred: false, funFact: "Serving your country doesn't always mean military - voting and paying taxes count too!", mnemonic: "Serve your country: Vote, Pay taxes, Obey law, Military. Many ways to serve!" },
  { id: 71, question: "Why is it important to pay federal taxes?", requiredAnswers: 1, acceptableAnswers: ["Required by law", "All people pay to fund the federal government", "Required by the (U.S.) Constitution (16th Amendment)", "Civic duty"], category: "Rights and Responsibilities", starred: false, funFact: "Federal taxes fund everything from defense to education to Social Security!", mnemonic: "Pay taxes = Required by LAW and civic duty. Taxes FUND the government!" },
  { id: 72, question: "It is important for all men age 18 through 25 to register for the Selective Service. Name one reason why.", requiredAnswers: 1, acceptableAnswers: ["Required by law", "Civic duty", "Makes the draft fair, if needed"], category: "Rights and Responsibilities", starred: false, funFact: "Men must register within 30 days of turning 18!", mnemonic: "Selective Service = Required by LAW. Men 18-25 must register!" },

  // AMERICAN HISTORY - Colonial Period and Independence (73-89)
  { id: 73, question: "The colonists came to America for many reasons. Name one.", requiredAnswers: 1, acceptableAnswers: ["Freedom", "Political liberty", "Religious freedom", "Economic opportunity", "Escape persecution"], category: "Colonial Period and Independence", starred: false, funFact: "Many colonists fled religious persecution in Europe to practice freely in America!", mnemonic: "Colonists wanted: Freedom, Religious freedom, Economic opportunity. Fresh start in new land!" },
  { id: 74, question: "Who lived in America before the Europeans arrived?", requiredAnswers: 1, acceptableAnswers: ["American Indians", "Native Americans"], category: "Colonial Period and Independence", starred: true, funFact: "Native Americans had been living in America for over 15,000 years before Europeans arrived!", mnemonic: "BEFORE Europeans = NATIVE Americans. They were here first - the original Americans!" },
  { id: 75, question: "What group of people was taken and sold as slaves?", requiredAnswers: 1, acceptableAnswers: ["Africans", "People from Africa"], category: "Colonial Period and Independence", starred: false, funFact: "The transatlantic slave trade forcibly brought millions of Africans to the Americas.", mnemonic: "AFRICANS were enslaved. People from AFRICA were taken and sold as slaves." },
  { id: 76, question: "What war did the Americans fight to win independence from Britain?", requiredAnswers: 1, acceptableAnswers: ["American Revolution", "The (American) Revolutionary War", "War for (American) Independence"], category: "Colonial Period and Independence", starred: false, funFact: "The Revolutionary War lasted from 1775 to 1783!", mnemonic: "American REVOLUTION = Won INDEPENDENCE from Britain. Revolutionary War freed America!" },
  { id: 77, question: "Name one reason why the Americans declared independence from Britain.", requiredAnswers: 1, acceptableAnswers: ["High taxes", "Taxation without representation", "British soldiers stayed in Americans' houses (boarding, quartering)", "They did not have self-government", "Boston Massacre", "Boston Tea Party (Tea Act)", "Stamp Act", "Sugar Act", "Townshend Acts", "Intolerable (Coercive) Acts"], category: "Colonial Period and Independence", starred: false, funFact: "'No taxation without representation' was the colonists' rallying cry!", mnemonic: "Easy answer: HIGH TAXES or Taxation without representation. Colonists were angry about unfair taxes!" },
  { id: 78, question: "Who wrote the Declaration of Independence?", requiredAnswers: 1, acceptableAnswers: ["(Thomas) Jefferson", "Thomas Jefferson", "Jefferson"], category: "Colonial Period and Independence", starred: true, funFact: "Jefferson wrote the Declaration when he was only 33 years old!", mnemonic: "Thomas JEFFERSON wrote the 'Dear John' letter to Britain - our Declaration of Independence!" },
  { id: 79, question: "When was the Declaration of Independence adopted?", requiredAnswers: 1, acceptableAnswers: ["July 4, 1776", "1776"], category: "Colonial Period and Independence", starred: false, funFact: "We celebrate July 4th as Independence Day every year!", mnemonic: "July 4, 1776 - that's why we celebrate July 4th! Easy to remember!" },
  { id: 80, question: "The American Revolution had many important events. Name one.", requiredAnswers: 1, acceptableAnswers: ["(Battle of) Bunker Hill", "Declaration of Independence", "Washington Crossing the Delaware (Battle of Trenton)", "(Battle of) Saratoga", "Valley Forge (Encampment)", "(Battle of) Yorktown (British surrender at Yorktown)"], category: "Colonial Period and Independence", starred: false, funFact: "The Battle of Yorktown was the final major battle that secured American independence!", mnemonic: "Easy: Declaration of Independence or Battle of Yorktown (final battle)!" },
  { id: 81, question: "There were 13 original states. Name five.", requiredAnswers: 5, acceptableAnswers: ["New Hampshire", "Massachusetts", "Rhode Island", "Connecticut", "New York", "New Jersey", "Pennsylvania", "Delaware", "Maryland", "Virginia", "North Carolina", "South Carolina", "Georgia"], category: "Colonial Period and Independence", starred: false, funFact: "The 13 stripes on the flag represent these 13 original colonies!", mnemonic: "Easy ones along the coast: New York, New Jersey, Pennsylvania, Virginia, Massachusetts. That's 5!" },
  { id: 82, question: "What founding document was written in 1787?", requiredAnswers: 1, acceptableAnswers: ["(U.S.) Constitution", "The Constitution"], category: "Colonial Period and Independence", starred: false, funFact: "The Constitution was written in Philadelphia at Independence Hall!", mnemonic: "1787 = The CONSTITUTION. Think 'Constitution Convention' in Philadelphia!" },
  { id: 83, question: "The Federalist Papers supported the passage of the U.S. Constitution. Name one of the writers.", requiredAnswers: 1, acceptableAnswers: ["(James) Madison", "(Alexander) Hamilton", "(John) Jay", "Publius", "Madison", "Hamilton", "Jay"], category: "Colonial Period and Independence", starred: false, funFact: "They wrote 85 essays under the pen name 'Publius' to promote the Constitution!", mnemonic: "MHJ: Madison, Hamilton, Jay wrote the Federalist Papers. Or just say 'Hamilton'!" },
  { id: 84, question: "Why were the Federalist Papers important?", requiredAnswers: 1, acceptableAnswers: ["They helped people understand the (U.S.) Constitution.", "They supported passing the (U.S.) Constitution."], category: "Colonial Period and Independence", starred: false, funFact: "The Federalist Papers are still studied today to understand the Constitution!", mnemonic: "Federalist Papers SUPPORTED the Constitution. Helped people UNDERSTAND it!" },
  { id: 85, question: "Benjamin Franklin is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["Founded the first free public libraries", "First Postmaster General of the United States", "Helped write the Declaration of Independence", "Inventor", "U.S. diplomat"], category: "Colonial Period and Independence", starred: false, funFact: "Franklin is on the $100 bill and invented bifocals and the lightning rod!", mnemonic: "Ben Franklin: Inventor (lightning rod), helped write Declaration, founded libraries. Multi-talented!" },
  { id: 86, question: "George Washington is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["\"Father of Our Country\"", "First president of the United States", "General of the Continental Army", "President of the Constitutional Convention"], category: "Colonial Period and Independence", starred: true, funFact: "Washington's face is on the $1 bill and the quarter!", mnemonic: "George Washington = 'Father of our Country' & FIRST President. Think Washington DC - named after him!" },
  { id: 87, question: "Thomas Jefferson is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["Writer of the Declaration of Independence", "Third president of the United States", "Doubled the size of the United States (Louisiana Purchase)", "First Secretary of State", "Founded the University of Virginia", "Writer of the Virginia Statute on Religious Freedom"], category: "Colonial Period and Independence", starred: false, funFact: "Jefferson is on the $2 bill and the nickel - and his face is on Mount Rushmore!", mnemonic: "Thomas Jefferson: Wrote Declaration of Independence, 3rd President, Louisiana Purchase. Pick one!" },
  { id: 88, question: "James Madison is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["\"Father of the Constitution\"", "Fourth president of the United States", "President during the War of 1812", "One of the writers of the Federalist Papers"], category: "Colonial Period and Independence", starred: false, funFact: "Madison was only 5'4\" - the shortest U.S. president!", mnemonic: "James Madison: 'Father of the Constitution', 4th President, Federalist Papers writer!" },
  { id: 89, question: "Alexander Hamilton is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["First Secretary of the Treasury", "One of the writers of the Federalist Papers", "Helped establish the First Bank of the United States", "Aide to General George Washington", "Member of the Continental Congress"], category: "Colonial Period and Independence", starred: false, funFact: "Hamilton is on the $10 bill and there's a hit Broadway musical about him!", mnemonic: "Alexander Hamilton: First Secretary of Treasury (money guy), Federalist Papers, founded First Bank!" },

  // 1800s (90-99)
  { id: 90, question: "What territory did the United States buy from France in 1803?", requiredAnswers: 1, acceptableAnswers: ["Louisiana Territory", "Louisiana"], category: "1800s", starred: false, funFact: "The Louisiana Purchase doubled the size of the U.S. for only $15 million!", mnemonic: "LOUISIANA Territory in 1803. Bought from France - doubled the size of America!" },
  { id: 91, question: "Name one war fought by the United States in the 1800s.", requiredAnswers: 1, acceptableAnswers: ["War of 1812", "Mexican-American War", "Civil War", "Spanish-American War"], category: "1800s", starred: false, funFact: "The Civil War (1861-1865) was the deadliest American war!", mnemonic: "1800s wars: War of 1812, Civil War (easiest!), Mexican-American, Spanish-American. Pick one!" },
  { id: 92, question: "Name the U.S. war between the North and the South.", requiredAnswers: 1, acceptableAnswers: ["The Civil War", "Civil War"], category: "1800s", starred: false, funFact: "The Civil War lasted from 1861 to 1865 and ended slavery!", mnemonic: "CIVIL War = Between CITIZENS. North vs South = Civil War!" },
  { id: 93, question: "The Civil War had many important events. Name one.", requiredAnswers: 1, acceptableAnswers: ["(Battle of) Fort Sumter", "Emancipation Proclamation", "(Battle of) Vicksburg", "(Battle of) Gettysburg", "Sherman's March", "(Surrender at) Appomattox", "(Battle of) Antietam/Sharpsburg", "Lincoln was assassinated."], category: "1800s", starred: false, funFact: "The Battle of Gettysburg had over 50,000 casualties in just 3 days!", mnemonic: "Easy: Emancipation Proclamation (freed slaves) or Battle of Gettysburg!" },
  { id: 94, question: "Abraham Lincoln is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["Freed the slaves (Emancipation Proclamation)", "Saved (or preserved) the Union", "Led the United States during the Civil War", "16th president of the United States", "Delivered the Gettysburg Address"], category: "1800s", starred: true, funFact: "Lincoln is on the $5 bill and the penny! He's also 6'4\" - tallest president!", mnemonic: "Lincoln FREED the slaves - think of him breaking chains! Emancipation = Freedom!" },
  { id: 95, question: "What did the Emancipation Proclamation do?", requiredAnswers: 1, acceptableAnswers: ["Freed the slaves", "Freed slaves in the Confederacy", "Freed slaves in the Confederate states", "Freed slaves in most Southern states"], category: "1800s", starred: false, funFact: "Lincoln issued it on January 1, 1863, during the Civil War!", mnemonic: "EMANCIPATION = FREEDOM. Emancipation Proclamation FREED the slaves!" },
  { id: 96, question: "What U.S. war ended slavery?", requiredAnswers: 1, acceptableAnswers: ["The Civil War", "Civil War"], category: "1800s", starred: false, funFact: "The 13th Amendment officially ended slavery after the Civil War in 1865!", mnemonic: "CIVIL War ended SLAVERY. North won, slavery ended!" },
  { id: 97, question: "What amendment says all persons born or naturalized in the United States, and subject to the jurisdiction thereof, are U.S. citizens?", requiredAnswers: 1, acceptableAnswers: ["14th Amendment", "The 14th Amendment"], category: "1800s", starred: false, funFact: "The 14th Amendment was passed in 1868 after the Civil War!", mnemonic: "14th Amendment = Citizenship for all born here. Birthright citizenship!" },
  { id: 98, question: "When did all men get the right to vote?", requiredAnswers: 1, acceptableAnswers: ["After the Civil War", "During Reconstruction", "(With the) 15th Amendment", "1870"], category: "1800s", starred: false, funFact: "The 15th Amendment gave voting rights regardless of race or color!", mnemonic: "AFTER the Civil War or 15th Amendment (1870). All men could vote!" },
  { id: 99, question: "Name one leader of the women's rights movement in the 1800s.", requiredAnswers: 1, acceptableAnswers: ["Susan B. Anthony", "Elizabeth Cady Stanton", "Sojourner Truth", "Harriet Tubman", "Lucretia Mott", "Lucy Stone"], category: "1800s", starred: false, funFact: "Susan B. Anthony is on the dollar coin!", mnemonic: "Susan B. Anthony (easiest!) or Elizabeth Cady Stanton. Women fought for the vote!" },

  // Recent American History (100-118)
  { id: 100, question: "Name one war fought by the United States in the 1900s.", requiredAnswers: 1, acceptableAnswers: ["World War I", "World War II", "Korean War", "Vietnam War", "(Persian) Gulf War"], category: "Recent American History", starred: false, funFact: "The U.S. fought in 5 major wars in the 1900s!", mnemonic: "1900s wars: WWI, WWII (easiest!), Korean, Vietnam, Gulf War. Pick one!" },
  { id: 101, question: "Why did the United States enter World War I?", requiredAnswers: 1, acceptableAnswers: ["Because Germany attacked U.S. (civilian) ships", "To support the Allied Powers (England, France, Italy, and Russia)", "To oppose the Central Powers (Germany, Austria-Hungary, the Ottoman Empire, and Bulgaria)"], category: "Recent American History", starred: false, funFact: "The sinking of the Lusitania by Germany in 1915 helped push the U.S. into WWI!", mnemonic: "WWI: Germany attacked U.S. ships. That brought America into the war!" },
  { id: 102, question: "When did all women get the right to vote?", requiredAnswers: 1, acceptableAnswers: ["1920", "After World War I", "(With the) 19th Amendment"], category: "Recent American History", starred: false, funFact: "It took 70 years of activism to win women's voting rights!", mnemonic: "1920 and 19th Amendment - both have 19! Women got the vote in 1920!" },
  { id: 103, question: "What was the Great Depression?", requiredAnswers: 1, acceptableAnswers: ["Longest economic recession in modern history"], category: "Recent American History", starred: false, funFact: "Unemployment reached 25% during the Great Depression!", mnemonic: "Great Depression = LONGEST economic recession. Very bad economic times!" },
  { id: 104, question: "When did the Great Depression start?", requiredAnswers: 1, acceptableAnswers: ["The Great Crash (1929)", "Stock market crash of 1929", "1929"], category: "Recent American History", starred: false, funFact: "Stock values dropped 90% from 1929 to 1932!", mnemonic: "1929 = Stock market CRASH started the Great Depression. Remember '29!" },
  { id: 105, question: "Who was president during the Great Depression and World War II?", requiredAnswers: 1, acceptableAnswers: ["(Franklin) Roosevelt", "Franklin Roosevelt", "FDR", "Roosevelt"], category: "Recent American History", starred: false, funFact: "FDR was elected 4 times - the only president to serve more than 2 terms!", mnemonic: "FDR = Franklin D. Roosevelt. He led through Depression and WWII!" },
  { id: 106, question: "Why did the United States enter World War II?", requiredAnswers: 1, acceptableAnswers: ["(Bombing of) Pearl Harbor", "Japanese attacked Pearl Harbor", "To support the Allied Powers (England, France, and Russia)", "To oppose the Axis Powers (Germany, Italy, and Japan)"], category: "Recent American History", starred: false, funFact: "Pearl Harbor was attacked on December 7, 1941 - 'a date which will live in infamy'!", mnemonic: "PEARL HARBOR! Japan attacked, and America entered WWII the next day!" },
  { id: 107, question: "Dwight Eisenhower is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["General during World War II", "President at the end of (during) the Korean War", "34th president of the United States", "Signed the Federal-Aid Highway Act of 1956 (Created the Interstate System)"], category: "Recent American History", starred: false, funFact: "Eisenhower was Supreme Commander of Allied Forces in WWII!", mnemonic: "Eisenhower: WWII General, 34th President, created Interstate Highway System!" },
  { id: 108, question: "Who was the United States' main rival during the Cold War?", requiredAnswers: 1, acceptableAnswers: ["Soviet Union", "USSR", "Russia"], category: "Recent American History", starred: false, funFact: "The Cold War lasted from 1947 to 1991 - no direct fighting, but lots of tension!", mnemonic: "COLD War = vs. SOVIET UNION (USSR). Russia was the rival!" },
  { id: 109, question: "During the Cold War, what was one main concern of the United States?", requiredAnswers: 1, acceptableAnswers: ["Communism", "Nuclear war"], category: "Recent American History", starred: false, funFact: "The Cuban Missile Crisis in 1962 almost started a nuclear war!", mnemonic: "Cold War concerns: COMMUNISM spreading or NUCLEAR war. Pick one!" },
  { id: 110, question: "Why did the United States enter the Korean War?", requiredAnswers: 1, acceptableAnswers: ["To stop the spread of communism"], category: "Recent American History", starred: false, funFact: "The Korean War lasted from 1950 to 1953 and Korea is still divided!", mnemonic: "Korean War = STOP COMMUNISM from spreading. Same reason for Vietnam War!" },
  { id: 111, question: "Why did the United States enter the Vietnam War?", requiredAnswers: 1, acceptableAnswers: ["To stop the spread of communism"], category: "Recent American History", starred: false, funFact: "The Vietnam War was the longest war in U.S. history until Afghanistan!", mnemonic: "Vietnam War = STOP COMMUNISM from spreading. Same as Korean War!" },
  { id: 112, question: "What did the civil rights movement do?", requiredAnswers: 1, acceptableAnswers: ["Fought to end racial discrimination"], category: "Recent American History", starred: false, funFact: "The Civil Rights Act of 1964 banned discrimination based on race!", mnemonic: "Civil Rights Movement = Fought to END RACIAL DISCRIMINATION. Equality for all!" },
  { id: 113, question: "Martin Luther King, Jr. is famous for many things. Name one.", requiredAnswers: 1, acceptableAnswers: ["Fought for civil rights", "Worked for equality for all Americans", "Worked to ensure that people would \"not be judged by the color of their skin, but by the content of their character\""], category: "Recent American History", starred: true, funFact: "MLK's 'I Have a Dream' speech in 1963 is one of the most famous speeches in history!", mnemonic: "MLK = Fought for CIVIL RIGHTS. Martin Luther KING was the KING of the civil rights movement!" },
  { id: 114, question: "Why did the United States enter the Persian Gulf War?", requiredAnswers: 1, acceptableAnswers: ["To force the Iraqi military from Kuwait"], category: "Recent American History", starred: false, funFact: "The Persian Gulf War lasted only 6 weeks in 1991!", mnemonic: "Persian Gulf War = Force IRAQ out of KUWAIT. Iraq invaded, we pushed them out!" },
  { id: 115, question: "What major event happened on September 11, 2001 in the United States?", requiredAnswers: 1, acceptableAnswers: ["Terrorists attacked the United States", "Terrorists took over two planes and crashed them into the World Trade Center in New York City", "Terrorists took over a plane and crashed into the Pentagon in Arlington, Virginia", "Terrorists took over a plane originally aimed at Washington, D.C., and crashed in a field in Pennsylvania"], category: "Recent American History", starred: true, funFact: "9/11 is now observed as Patriot Day to remember the nearly 3,000 victims.", mnemonic: "9/11 = September 11, 2001. Terrorist attacks on America. The date itself became the shorthand name." },
  { id: 116, question: "Name one U.S. military conflict after the September 11, 2001 attacks.", requiredAnswers: 1, acceptableAnswers: ["(Global) War on Terror", "War in Afghanistan", "War in Iraq"], category: "Recent American History", starred: false, funFact: "The War in Afghanistan was America's longest war, lasting 20 years!", mnemonic: "After 9/11: War on Terror, Afghanistan, or Iraq. Any of these works!" },
  { id: 117, question: "Name one American Indian tribe in the United States.", requiredAnswers: 1, acceptableAnswers: ["Apache", "Blackfeet", "Cayuga", "Cherokee", "Cheyenne", "Chippewa", "Choctaw", "Creek", "Crow", "Hopi", "Huron", "Inupiat", "Lakota", "Mohawk", "Mohegan", "Navajo", "Oneida", "Onondaga", "Pueblo", "Seminole", "Seneca", "Shawnee", "Sioux", "Teton", "Tuscarora"], category: "Recent American History", starred: false, funFact: "There are 574 federally recognized Native American tribes in the U.S.!", mnemonic: "Easy tribes: Cherokee, Navajo, Sioux, Apache. Pick the one you remember!" },
  { id: 118, question: "Name one example of an American innovation.", requiredAnswers: 1, acceptableAnswers: ["Light bulb", "Automobile (cars, internal combustion engine)", "Skyscrapers", "Airplane", "Assembly line", "Landing on the moon", "Integrated circuit (IC)"], category: "Recent American History", starred: false, funFact: "America was first to land on the moon in 1969!", mnemonic: "American innovations: Light bulb, Airplane, Landing on the moon. Pick one!" },

  // SYMBOLS AND HOLIDAYS (119-128)
  { id: 119, question: "What is the capital of the United States?", requiredAnswers: 1, acceptableAnswers: ["Washington, D.C.", "Washington DC", "D.C."], category: "Symbols", starred: false, funFact: "D.C. stands for District of Columbia, named after Christopher Columbus!", mnemonic: "Washington, D.C. is the capital. D.C. = District of Columbia!" },
  { id: 120, question: "Where is the Statue of Liberty?", requiredAnswers: 1, acceptableAnswers: ["New York (Harbor)", "Liberty Island", "New Jersey", "Near New York City", "On the Hudson (River)"], category: "Symbols", starred: false, funFact: "The Statue of Liberty was a gift from France in 1886!", mnemonic: "Statue of Liberty = NEW YORK Harbor. Think of the New York skyline!" },
  { id: 121, question: "Why does the flag have 13 stripes?", requiredAnswers: 1, acceptableAnswers: ["(Because there were) 13 original colonies", "(Because the stripes) represent the original colonies"], category: "Symbols", starred: true, funFact: "The 13 stripes represent the 13 original colonies that declared independence from Britain!", mnemonic: "13 stripes = 13 original colonies. Count the stripes on the flag - 7 red, 6 white = 13 total!" },
  { id: 122, question: "Why does the flag have 50 stars?", requiredAnswers: 1, acceptableAnswers: ["(Because there is) one star for each state", "(Because) each star represents a state", "(Because there are) 50 states"], category: "Symbols", starred: false, funFact: "Hawaii was the 50th state added in 1959, completing the 50 stars!", mnemonic: "50 stars = 50 states. One star for each state!" },
  { id: 123, question: "What is the name of the national anthem?", requiredAnswers: 1, acceptableAnswers: ["The Star-Spangled Banner"], category: "Symbols", starred: false, funFact: "Francis Scott Key wrote 'The Star-Spangled Banner' during the War of 1812!", mnemonic: "National anthem = 'The STAR-SPANGLED BANNER.' Think of stars on the flag!" },
  { id: 124, question: "The Nation's first motto was 'E Pluribus Unum.' What does that mean?", requiredAnswers: 1, acceptableAnswers: ["Out of many, one", "We all become one"], category: "Symbols", starred: false, funFact: "E Pluribus Unum appears on U.S. coins and the Great Seal!", mnemonic: "E Pluribus Unum = OUT OF MANY, ONE. Many states, one nation!" },
  { id: 125, question: "What is Independence Day?", requiredAnswers: 1, acceptableAnswers: ["A holiday to celebrate U.S. independence (from Britain)", "The country's birthday"], category: "Holidays", starred: false, funFact: "Independence Day is July 4th - the day we declared independence in 1776!", mnemonic: "Independence Day = U.S. INDEPENDENCE from Britain. The country's birthday!" },
  { id: 126, question: "Name three national U.S. holidays.", requiredAnswers: 3, acceptableAnswers: ["New Year's Day", "Martin Luther King, Jr. Day", "Presidents Day (Washington's Birthday)", "Memorial Day", "Juneteenth", "Independence Day", "Labor Day", "Columbus Day", "Veterans Day", "Thanksgiving Day", "Christmas Day"], category: "Holidays", starred: true, funFact: "There are 11 federal holidays in the United States!", mnemonic: "Easy ones: New Year's, Independence Day (July 4th), Thanksgiving, Christmas. Pick any 3!" },
  { id: 127, question: "What is Memorial Day?", requiredAnswers: 1, acceptableAnswers: ["A holiday to honor soldiers who died in military service"], category: "Holidays", starred: false, funFact: "Memorial Day is observed on the last Monday in May!", mnemonic: "MEMORIAL Day = Remember soldiers who DIED. Memorials honor the dead!" },
  { id: 128, question: "What is Veterans Day?", requiredAnswers: 1, acceptableAnswers: ["A holiday to honor people in the (U.S.) military", "A holiday to honor people who have served (in the U.S. military)"], category: "Holidays", starred: false, funFact: "Veterans Day is November 11th - the date WWI ended!", mnemonic: "VETERANS Day = Honor all VETERANS (people who served). Living veterans!" }
];

